<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Publish software | AROSOFT Labs</title><style>body{font:15px/1.5 system-ui;max-width:850px;margin:30px auto;padding:20px;color:#142941}form{display:grid;grid-template-columns:1fr 1fr;gap:15px}label{display:flex;flex-direction:column;gap:5px}input,textarea,select{padding:11px;border:1px solid #cbd5e1;border-radius:8px;font:inherit}.wide{grid-column:1/-1}button{background:#245bb6;color:white;border:0;padding:13px 22px;border-radius:8px}@media(max-width:600px){form{grid-template-columns:1fr}.wide{grid-column:auto}}</style></head><body><a href="{{ route('admin.labs.index') }}">← Products</a><h1>{{ $product->exists?'Edit':'Publish' }} software</h1>@if(session('notice'))<p role="status">{{ session('notice') }}</p>@endif@if($errors->any())<ul>@foreach($errors->all() as $e)<li>{{ $e }}</li>@endforeach</ul>@endif<form method="post" action="{{ $product->exists?route('admin.labs.update',$product):route('admin.labs.store') }}">@csrf@if($product->exists)@method('PUT')@endif<label>Name<input name="name" required value="{{ old('name',$product->name) }}"></label><label>Platform<select name="kind">@foreach(['desktop'=>'Desktop','web_app'=>'Web / cloud','mobile_app'=>'Mobile','website'=>'Website'] as $key=>$label)<option value="{{ $key }}" @selected(old('kind',$product->kind)===$key)>{{ $label }}</option>@endforeach</select></label><label class="wide">Summary<textarea name="summary">{{ old('summary',$product->summary) }}</textarea></label><label class="wide">Description<textarea name="description" rows="6">{{ old('description',$product->description) }}</textarea></label><label>Price<input name="price" type="number" min="0" step=".01" value="{{ old('price',$product->price) }}"></label><label>Currency<select name="currency">@foreach(['USD','UGX'] as $c)<option @selected(old('currency',$product->currency?:'USD')===$c)>{{ $c }}</option>@endforeach</select></label><label>Billing<select name="billing_type">@foreach(['quote','free','one_time','subscription'] as $c)<option value="{{ $c }}" @selected(old('billing_type',$product->billing_type?:'quote')===$c)>{{ $c }}</option>@endforeach</select></label><label>Status<select name="status">@foreach(['draft','published','archived'] as $c)<option @selected(old('status',$product->status?:'draft')===$c)>{{ $c }}</option>@endforeach</select></label><label class="wide">Demo URL<input name="demo_url" type="url" value="{{ old('demo_url',$product->exists?$product->links()->where('purpose','demo')->value('url'):'') }}"></label><label>Android Play Store URL<input name="android_url" type="url" value="{{ old('android_url',$product->exists?$product->links()->where('platform','android')->value('url'):'') }}"></label><label>iOS App Store URL<input name="ios_url" type="url" value="{{ old('ios_url',$product->exists?$product->links()->where('platform','ios')->value('url'):'') }}"></label><label class="wide">Installer download URL<input name="download_url" type="url" value="{{ old('download_url',$product->exists?$product->links()->where('purpose','download')->value('url'):'') }}"></label><label class="wide">Screenshot URLs (one HTTPS URL per line)<textarea name="screenshots" rows="5">{{ old('screenshots',$product->exists?$product->media()->where('type','screenshot')->pluck('path_or_url')->implode("\n"):'') }}</textarea></label><label class="wide"><span><input type="checkbox" name="featured" value="1" @checked(old('featured',$product->featured))> Featured product</span></label><div class="wide"><button type="submit">Save product</button></div></form></body></html>
